/bin/bash -lc "cat > src/semantic_version_precedence.ts <<'EOF'
function parts(value: string): { core: string[]; prerelease: string[] } {
  if ("'!/''^(0|[1-9][0-9]*)'"\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?"'$(?!['"\\s\\S])/.test(value)) {
    throw new Error(\"invalid version\");
  }
  const main = value.split(\"+\")[0];
  const dash = main.indexOf(\"-\");
  const prerelease = dash < 0 ? [] : main.slice(dash + 1).split(\".\");
  if (prerelease.some(identifier => /"'^[0-9]+$/.test(identifier) && identifier.length > 1 && identifier.startsWith("0"))) {
    throw new Error("leading zero");
  }
  return { core: (dash < 0 ? main : main.slice(0, dash)).split("."), prerelease };
}

// Validated numeric identifiers have no leading zeroes, so length and lexical
// order preserve their exact numeric order without converting to Number.
function compareNumeric(left: string, right: string): number {
  if (left.length !== right.length) return left.length < right.length ? -1 : 1;
  return left === right ? 0 : left < right ? -1 : 1;
}

export function compareVersions(left: string, right: string): number {
  const a = parts(left);
  const b = parts(right);
  for (let i = 0; i < a.core.length; i++) {
    const comparison = compareNumeric(a.core[i], b.core[i]);
    if (comparison !== 0) return comparison;
  }
  if (a.prerelease.length === 0 || b.prerelease.length === 0) {
    return a.prerelease.length === b.prerelease.length ? 0 : a.prerelease.length === 0 ? 1 : -1;
  }
  for (let i = 0; i < Math.min(a.prerelease.length, b.prerelease.length); i++) {
    const x = a.prerelease[i];
    const y = b.prerelease[i];
    if (x === y) continue;
    const xNumeric = /''^[0-9]+$/.test(x);
    const yNumeric = /''^[0-9]+$/.test(y);
    if (xNumeric && yNumeric) return compareNumeric(x, y);
    if (xNumeric !== yNumeric) return xNumeric ? -1 : 1;
    return x < y ? -1 : 1;
  }
  return a.prerelease.length === b.prerelease.length ? 0 : a.prerelease.length < b.prerelease.length ? -1 : 1;
}
EOF
cat > tests/semantic_version_precedence.test.mjs <<'"'EOF'
import test from \"node:test\";
import assert from \"node:assert/strict\";
import { compareVersions as domainCompare } from \"../src/semantic_version_precedence.ts\";
import { compareVersions as apiCompare } from \"../src/api.ts\";

for (const [name, compare] of [[\"domain\", domainCompare], [\"api\", apiCompare]]) {
  test("'`${name}: semantic precedence and exact numeric ordering`, () => {
    const ordered = [
      "1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta",
      "1.0.0-beta", "1.0.0-beta.2", "1.0.0-beta.11",
      "1.0.0-rc.1", "1.0.0", "1.0.1", "1.1.0", "1.10.0", "2.0.0", "10.0.0",
    ];
    for (let i = 0; i < ordered.length; i++) {
      for (let j = 0; j < ordered.length; j++) {
        assert.equal(compare(ordered[i], ordered[j]), i === j ? 0 : i < j ? -1 : 1);
      }
    }
    for (const [left, right] of [
      ["9007199254740992.0.0", "9007199254740993.0.0"],
      ["1.9007199254740992.0", "1.9007199254740993.0"],
      ["1.0.999999999999999999999", "1.0.1000000000000000000000"],
      ["1.0.0-9007199254740992", "1.0.0-9007199254740993"],
      ["1.0.0-999999999999999999999", "1.0.0-1000000000000000000000"],
      ["1.0.0-999999999999999999999", "1.0.0--"],
      ["1.0.0-A", "1.0.0-a"],
    ]) {
      assert.equal(compare(left, right), -1);
      assert.equal(compare(right, left), 1);
    }
    assert.equal(compare("1.2.3+001.foo-bar", "1.2.3+other"), 0);
    assert.equal(compare("1.2.3-alpha.0+001", "1.2.3-alpha.0"), 0);
  });

  test(`${name}: rejects invalid syntax on either side`, () => {
    for (const invalid of [
      "", "1", "1.2", "1.2.3.4", "01.2.3", "1.02.3", "1.2.03",
      "-1.2.3", "v1.2.3", "1.2.3-", "1.2.3-01", "1.2.3-alpha.00",
      "1.2.3-a..b", "1.2.3-a_b", "1.2.3-é", "1.2.3+", "1.2.3+a..b",
      "1.2.3+a_b", "1.2.3+a+b", " 1.2.3", "1.2.3'"\\n\", \"1.2.3\\r\\n\",
    ]) {
      assert.throws(() => compare(invalid, \"1.2.3\"), undefined, invalid);
      assert.throws(() => compare(\"1.2.3\", invalid), undefined, invalid);
    }
  });
}
EOF
